THEORY, QUESTIONS, MODELS = [], [], []

def view(points=(), segments=(), **kw):
    return dict(label=kw.pop('label', 'Условие'), points=list(points), segments=[list(p) for p in segments], **kw)

def arc(o, a, b, marks=0, radius=7):
    return {'vertex':o, 'from':a, 'to':b, 'radius':radius, 'marks':marks}

def eq(a,b,marks=1): return dict(a=a,b=b,marks=marks)
def right(a,o,b): return dict(a=a,vertex=o,b=b)
def circle(o,p): return dict(center=o,through=p)
def check(kind, **kw): return dict(type=kind, **kw)
def equal(*pairs): return check('equalLength', segments=[list(p) for p in pairs])
def col(*ps): return check('collinear',points=list(ps))
def perp(a,b,c,d): return check('perpendicular',segments=[[a,b],[c,d]])

def model(points, initial, scenes, checks=(), cases=(), labels=None, offsets=None, note=''):
    views={'neutral':deepcopy(initial)}
    for i,s in enumerate(scenes,1):
        views[f'step-{i}']=deepcopy(s); views[f'step-{i}']['label']=f'Шаг {i}'
    for i,s in enumerate(cases,1): views[f'case-{i}']=deepcopy(s)
    m=dict(points={k:[round(float(x),9),round(float(y),9),0] for k,(x,y) in points.items()},edges=[],planar=True,bounds=[0,0,100,70],views=views,checks=list(checks),description=note or 'На каждом шаге показаны только нужные для рассуждения элементы. Условия и объяснения находятся рядом с чертежом.')
    if labels: m['labels']=labels
    if offsets: m['labelOffsets']=offsets
    return m

def step(prompt, explanation, justification, refs):
    return dict(prompt=prompt, explanation=explanation, justification=justification, theoryPoints=list(refs))

def add(collection, number, title, pages, statement, rows, answer, m, notes=()):
    assert len(rows)==sum(k.startswith('step-') for k in m['views']), (collection,number)
    did={'steps':[{k:v for k,v in s.items() if k!='explanation'} for s in rows]}
    record=dict(number=number,title=title,printedPages=pages,pdfPages=[p+1 for p in pages],statement=statement,steps=[s['explanation'] for s in rows],answer=answer,didactics=did,sourceVerified=True,mathVerified=True,notes=list(notes))
    (THEORY if collection=='theory' else QUESTIONS).append(record)
    MODELS.append(dict(chapter=2,collection=collection,number=number,part='single',model=m,didactics=deepcopy(did)))
    return record

def pair_model(mode, nsteps):
    p={'A':(16,17),'B':(42,17),'C':(25,53),'A1':(59,17),'B1':(85,17),'C1':(68,53)}
    edges=[['A','B'],['B','C'],['C','A'],['A1','B1'],['B1','C1'],['C1','A1']]
    v=view(p,edges)
    if mode=='SAS':
        v['equalSegments']=[eq('A','B'),eq('A1','B1'),eq('A','C',2),eq('A1','C1',2)]
        v['angleArcs']=[arc('A','B','C',1),arc('A1','B1','C1',1)]
    elif mode=='ASA':
        v['equalSegments']=[eq('A','B'),eq('A1','B1')]
        v['angleArcs']=[arc('A','B','C',1),arc('A1','B1','C1',1),arc('B','A','C',2),arc('B1','A1','C1',2)]
    elif mode=='SSS': v['equalSegments']=[eq('A','B'),eq('A1','B1'),eq('A','C',2),eq('A1','C1',2),eq('B','C',3),eq('B1','C1',3)]
    scenes=[deepcopy(v) for _ in range(nsteps)]
    if nsteps>1:
        scenes[1]['highlightSegments']=[['A','B'],['A1','B1']]
    if nsteps>2:
        scenes[2]['highlightSegments']=[['A','C'],['A1','C1']]
    if nsteps>3:
        scenes[3]['highlightSegments']=[['B','C'],['B1','C1']]
    return model(p,v,scenes,[equal(('A','B'),('A1','B1')),equal(('A','C'),('A1','C1')),equal(('B','C'),('B1','C1'))],labels={'A1':'A₁','B1':'B₁','C1':'C₁'},offsets={'A':(-3,-5),'B':(3,-5),'C':(-1,5),'A1':(-3,-5),'B1':(3,-5),'C1':(-1,5)})

