def perpendicular_model(nsteps=6):
    p={'A':(63,55),'A1':(63,15),'B':(20,35),'C':(85,35),'H':(63,35)}
    neutral=view(['A','B','C'],lines=[['B','C']])
    v1=deepcopy(neutral)
    v2=view(['A','B','C'],[['A','B']],lines=[['B','C']])
    v3=view(['A','A1','B','C'],[['A','B'],['A1','B']],lines=[['B','C']],angleArcs=[arc('B','A','C',1),arc('B','C','A1',1)])
    v4=view(['A','A1','B','H'],[['A','B'],['A1','B'],['A','A1']],lines=[['B','C']],angleArcs=[arc('H','B','A',1),arc('H','A1','B',1)])
    v5=view(['A','H','B','C'],[['A','H']],lines=[['B','C']],rightAngles=[right('A','H','C')])
    seq=[v1,v2,v3,v4,v5,v5]
    return model(p,neutral,seq[:nsteps],[equal(('B','A'),('B','A1')),col('B','H','C'),col('A','H','A1'),perp('A','H','B','C')],labels={'A1':'A₁'},offsets={'A':(2,5),'A1':(2,-5),'H':(3,-5),'B':(-3,4),'C':(3,4)})

