def triangle_aux():
    A=(36,57);B=(15,15);C=(85,15)
    ab=math.dist(A,B);ac=math.dist(A,C);d=(ac*B[0]+ab*C[0])/(ab+ac)
    p={'A':A,'B':B,'C':C,'M':(50,15),'D':(d,15),'H':(36,15),'Ao':(30,35),'Bo':(50,15),'Co':(85,15),'Ho':(30,15),'Ar':(30,53),'Br':(30,15),'Cr':(80,15)}
    edges=[['A','B'],['B','C'],['C','A']]
    base=view(['A','B','C'],edges)
    median=view(['A','B','C','M'],edges+[['A','M']],equalSegments=[eq('B','M'),eq('M','C')])
    bis=view(['A','B','C','D'],edges+[['A','D']],angleArcs=[arc('A','B','D',1),arc('A','D','C',1)])
    height=view(['A','B','C','H'],edges+[['A','H']],rightAngles=[right('A','H','C')])
    obtuse=view(['Ao','Bo','Co','Ho'],[['Ao','Bo'],['Bo','Co'],['Co','Ao'],['Ao','Ho']],dashSegments=[['Ho','Bo']],rightAngles=[right('Ao','Ho','Bo')],note='Основание высоты может лежать на продолжении стороны.')
    rect=view(['Ar','Br','Cr'],[['Ar','Br'],['Br','Cr'],['Cr','Ar']],highlightSegments=[['Ar','Br']],rightAngles=[right('Ar','Br','Cr')],note='В прямоугольном треугольнике две высоты совпадают с катетами.')
    claims=[col('B','M','C'),equal(('B','M'),('M','C')),col('B','D','C'),perp('A','H','B','C'),perp('Ao','Ho','Bo','Co'),perp('Ar','Br','Br','Cr')]
    return p,base,median,bis,height,obtuse,rect,claims

