def sss_model(nsteps=7):
    initial=pair_model('SSS',1)
    p={k:v[:2] for k,v in initial['points'].items()}
    checks=deepcopy(initial['checks']); labels=deepcopy(initial['labels'])
    variants=[]; plain=[]
    for prefix,ay,by,cy in [('i',58,12,35),('b',58,35,35),('o',43,12,58)]:
        a,b,c,d=[prefix+s for s in ['A','B','C','D']]
        p.update({a:(50,ay),b:(50,by),c:(22,cy),d:(78,cy)})
        labels.update({a:'A',b:'B',c:'C',d:'C₁'})
        edges=[[a,b],[a,c],[b,c],[a,d],[b,d]]
        z=view([a,b,c,d],edges,equalSegments=[eq(a,c),eq(a,d),eq(b,c,2),eq(b,d,2)])
        plain.append(deepcopy(z))
        if prefix!='b': z['dashSegments']=[[c,d]]
        z['angleArcs']=[arc(c,a,d,1),arc(d,a,c,1)]
        if prefix!='b': z['angleArcs'] += [arc(c,b,d,2,10),arc(d,b,c,2,10)]
        variants.append(z)
        checks += [equal((a,c),(a,d)),equal((b,c),(b,d))]
    variants[0].update(label='Луч внутри угла',availableFromStep=3)
    variants[1].update(label='Луч на стороне угла',availableFromStep=4)
    variants[2].update(label='Луч вне угла',availableFromStep=5)
    seq=[initial['views']['neutral'],plain[0],variants[0],variants[1],variants[2],plain[0],view(['A','B','C'],[['A','B'],['B','C'],['C','A']])]
    return model(p,initial['views']['neutral'],seq[:nsteps],checks,variants,labels=labels,offsets={'iA':(0,5),'iB':(0,-5),'iC':(-4,0),'iD':(4,0),'bA':(0,5),'bB':(0,-6),'bC':(-4,0),'bD':(4,0),'oA':(4,0),'oB':(0,-5),'oC':(-4,4),'oD':(4,4)})

sssrows=[
 step('Какие данные составляют третий признак?','Пусть AB=A₁B₁, AC=A₁C₁, BC=B₁C₁. Докажем, что △ABC=△A₁B₁C₁: достаточно попарного равенства всех трёх сторон.','Условие третьего признака',[20]),
 step('Как приложить треугольники общей стороной?','Совместим равные AB и A₁B₁, расположив C и C₁ по разные стороны общей прямой AB. Совмещённые вершины обозначаем A и B. Имеем AC=AC₁ и BC=BC₁. Соединим C и C₁.','Равенство отрезков и наложение',[5,20]),
 step('Что делать, если CC₁ проходит внутри углов при C и C₁?','Треугольники ACC₁ и BCC₁ равнобедренные. Поэтому ∠ACC₁=∠AC₁C и ∠BCC₁=∠BC₁C. Складывая равные углы, получаем ∠ACB=∠AC₁B.','Углы при основании равнобедренного треугольника; сложение углов',[9,18]),
 step('Как разобрать случай, когда CC₁ совпал со стороной угла?','Пусть B лежит на CC₁ между C и C₁. Тогда ∠ACB=∠ACC₁ и ∠AC₁B=∠AC₁C; эти углы равны в равнобедренном ACC₁. Если на CC₁ лежит A, рассуждаем так же с равнобедренным BCC₁.','Углы при основании; совпадение лучей',[18,20]),
 step('Как разобрать случай, когда CC₁ вне обоих углов?','На отдельном чертеже A ближе к CC₁, чем B. Из равнобедренных ACC₁ и BCC₁ получаем две пары равных углов. Вычитаем: ∠ACB=∠BCC₁−∠ACC₁ и ∠AC₁B=∠BC₁C−∠AC₁C; разности равны. При обратном расположении A и B меняем их роли.','Вычитание равных углов; свойства равнобедренного треугольника',[9,18]),
 step('Как теперь завершить доказательство?','Во всех трёх случаях ∠ACB=∠AC₁B. Стороны AC=AC₁ и BC=BC₁ даны. По двум сторонам и углу между ними △ACB=△AC₁B. Возвращая исходные обозначения, получаем △ABC=△A₁B₁C₁.','Первый признак равенства треугольников',[15,20]),
 step('Почему треугольник называют жёсткой фигурой?','Если длины трёх сторон закреплены, изменить углы и получить неравный треугольник нельзя: третий признак снова даст равенство. Поэтому диагональная подпорка, замыкающая треугольник, делает конструкцию жёсткой. Это геометрическая модель: реальные материалы могут деформироваться.','Следствие третьего признака',[20])]
add('theory',20,'Третий признак и жёсткость треугольника',[39,40,41],
 'Докажем равенство треугольников по трём сторонам, разобрав все три расположения вспомогательного отрезка.',sssrows,
 'Три пары соответственно равных сторон обеспечивают равенство треугольников; это объясняет жёсткость треугольника.',sss_model())

def circle_model(nsteps=6):
    p={'O':(50,35),'A':(26,35),'B':(74,35),'C':(38,35+12*math.sqrt(3)),'D':(62,35+12*math.sqrt(3)),'E':(50,59),'F':(50,11)}
    contour=[circle('O','A')]
    base=view(['O'],circles=contour)
    radius=view(['O','A'],[['O','A']],circles=contour)
    chord=view(['C','D'],[['C','D']],circles=contour)
    diameter=view(['A','O','B'],[['A','B']],circles=contour,equalSegments=[eq('A','O'),eq('O','B')])
    arcs=view(['C','D','E','F'],circles=contour,angleArcs=[arc('O','C','D',0,24)],note='C и D — общие концы двух дуг: одна проходит через E, другая — через F.')
    disk=view(['O'],circles=contour,note='Окружность — только граница. Круг включает эту границу и все точки внутри неё.')
    return model(p,base,[base,radius,chord,diameter,arcs,disk][:nsteps],[equal(('O','A'),('O','B'),('O','C'),('O','D'),('O','E'),('O','F')),col('A','O','B'),check('distanceRatio',segments=[['A','B'],['O','A']],ratio=2)],offsets={'O':(3,-4),'A':(-4,0),'B':(4,0),'C':(-4,5),'D':(4,5),'E':(0,6),'F':(0,-6)})

circlerows=[
 step('Для чего нужно определение?','Определение поясняет точный смысл названия. Окружность с центром O и радиусом r>0 состоит из всех точек плоскости, расстояние от которых до O равно r.','Определение окружности',[21]),
 step('Что такое радиус?','Отрезок от O до любой точки окружности — радиус. Все радиусы одной окружности имеют одинаковую длину r, потому что так выбраны её точки.','Равные расстояния в определении окружности',[21]),
 step('Что такое хорда?','Хорда соединяет две точки окружности. Например, CD — хорда; её концы находятся на окружности, а центр не обязан лежать на хорде.','Определение хорды',[21]),
 step('Чем диаметр отличается от других хорд?','Диаметр — хорда, проходящая через O. На диаметре AB имеем AO=OB=r, поэтому AB=2r, а O — середина диаметра.','Равенство радиусов и сложение отрезков',[7,21]),
 step('Что называют дугами?','Две разные точки C и D разделяют окружность на две части. Каждая — дуга с концами C и D. Для различения можно указать третью точку: дуга CED и дуга CFD.','Определение дуги',[21]),
 step('Чем круг отличается от окружности?','Окружность — граница; круг — область внутри неё вместе с этой границей. Циркуль рисует окружность, а не закрашенную внутреннюю область.','Определение круга',[21])]
add('theory',21,'Окружность, радиус, хорда и диаметр',[43,44],
 'Разберём элементы окружности и отличие окружности от круга.',circlerows,
 'Радиусы одной окружности равны; диаметр — хорда через центр, d=2r. Круг включает внутреннюю область.',circle_model())

def segment_copy_model(nsteps=4):
    p={'A':(15,58),'B':(35,58),'O':(44,25),'C':(89,25),'D':(64,25)}
    base=view(['A','B','O','C'],[['A','B']],rays=[['O','C']])
    compass=view(['A','B','O','C'],[['A','B']],rays=[['O','C']],circles=[circle('O','D')])
    found=view(['A','B','O','D','C'],[['A','B'],['O','D']],rays=[['O','C']],circles=[circle('O','D')])
    final=view(['A','B','O','D','C'],[['A','B'],['O','D']],rays=[['O','C']],equalSegments=[eq('A','B'),eq('O','D')])
    return model(p,base,[base,compass,found,final][:nsteps],[equal(('A','B'),('O','D')),col('O','D','C')],offsets={'A':(-3,5),'B':(3,5),'O':(-3,-5),'D':(0,-5),'C':(0,-5)})

copyrows=[
 step('Какие действия разрешены инструментами?','Линейка без делений проводит прямую, в частности через две заданные точки. Циркуль строит окружность с заданным центром и радиусом, равным данному отрезку. Измерять числа по делениям линейки или пользоваться транспортиром в такой задаче нельзя.','Условия построений циркулем и линейкой',[22]),
 step('Как перенести длину AB на луч OC?','Раскроем циркуль на длину AB и построим окружность с центром O и этим радиусом. На рисунке круговая линия относится только к этому шагу построения.','Построение окружности заданного радиуса',[21,22]),
 step('Как выбрать конец искомого отрезка?','Обозначим D точку пересечения окружности с лучом OC. Берём точку именно на луче, а не на его продолжении в противоположную сторону.','Пересечение луча с окружностью, центр которой — начало луча',[3,21]),
 step('Почему OD — нужный отрезок?','OD — радиус построенной окружности, поэтому OD=AB. Отрезок начинается в O и лежит на OC. При AB>0 такая точка D на данном луче единственна.','Определение окружности; откладывание отрезка на луче',[7,21,22])]
add('theory',22,'Построения циркулем и линейкой',[44,45],
 'Обсудим разрешённые действия и отложим на луче OC от его начала отрезок, равный AB.',copyrows,
 'Нужный конец — пересечение луча с окружностью, центр которой в начале луча, а радиус равен данному отрезку.',segment_copy_model())

def angle_copy():
    r=18;theta=math.radians(50)
    p={'A':(20,40),'B':(38,40),'C':(20+r*math.cos(theta),40+r*math.sin(theta)),'K':(45,40),'L':(20+26*math.cos(theta),40+26*math.sin(theta)),'O':(62,22),'M':(89,22),'D':(80,22),'E':(62+r*math.cos(theta),22+r*math.sin(theta))}
    base=view(['A','K','L','O','M'],[['A','K'],['A','L']],rays=[['O','M']])
    first=view(['A','B','C','O','M'],[['A','K'],['A','L']],rays=[['O','M']],circles=[circle('A','B')])
    second=view(['A','B','C','O','D','M'],[['A','B'],['A','C'],['B','C']],rays=[['O','M']],circles=[circle('O','D')])
    third=view(['A','B','C','O','D','E'],[['A','B'],['A','C'],['B','C']],rays=[['O','M']],circles=[circle('O','D'),circle('D','E')])
    proof=view(['A','B','C','O','D','E'],[['A','B'],['A','C'],['B','C'],['O','D'],['O','E'],['D','E']],equalSegments=[eq('A','B'),eq('A','C'),eq('O','D'),eq('O','E'),eq('B','C',2),eq('D','E',2)])
    final=view(['A','B','C','O','D','E'],[['A','B'],['A','C'],['O','D'],['O','E']],angleArcs=[arc('A','B','C',1),arc('O','D','E',1)])
    checks=[equal(('A','B'),('A','C'),('O','D'),('O','E')),equal(('B','C'),('D','E')),col('O','D','M')]
    rows=[
      step('С чего начинается перенос угла?','Дан угол KAL и луч OM. Окружностью произвольного радиуса с центром A отметим B на AK и C на AL. Получим AB=AC.','Радиусы одной окружности',[21,23]),
      step('Как перенести тот же радиус?','Построим окружность того же радиуса с центром O. Её пересечение с лучом OM обозначим D. Тогда OD=AB=AC.','Окружность с заданным радиусом',[21,22,23]),
      step('Как определить направление второго луча?','Построим окружность с центром D и радиусом BC. Одно из её пересечений с окружностью центра O обозначим E. Проводим OE; выбор пересечения задаёт сторону от OM, в которую откладывается угол.','Пересечение двух окружностей',[21,23]),
      step('Почему угол получился равным данному?','В △ABC и △ODE имеем AB=OD, AC=OE и BC=DE по построению. По третьему признаку треугольники равны, значит ∠BAC=∠DOE=∠MOE.','Третий признак; соответствующие углы',[14,20,23]),
      step('Что остаётся после завершения построения?','Искомый угол образован лучами OM и OE. Вспомогательные окружности можно убрать с рабочего чертежа, сохранив ход построения в предыдущих шагах.','Проверка построенного объекта',[23])]
    return p,base,[first,second,third,proof,final],checks,rows

def bisector_build():
    h=10*math.sqrt(3)
    p={'A':(50,20),'B':(40,20+h),'C':(60,20+h),'K':(30,20+2*h),'M':(70,20+2*h),'E':(50,20+2*h)}
    # Keep the full construction circle and its stroke above the lower viewport.
    p={name:(x,y+3) for name,(x,y) in p.items()}
    base=view(['A','K','M'],[['A','K'],['A','M']])
    first=view(['A','B','C'],[['A','K'],['A','M']],circles=[circle('A','B')])
    second=view(['A','B','C','E'],[['A','K'],['A','M']],circles=[circle('B','C'),circle('C','B')])
    proof=view(['A','B','C','E'],[['A','B'],['A','C'],['B','E'],['C','E'],['A','E']],equalSegments=[eq('A','B'),eq('A','C'),eq('B','E',2),eq('C','E',2)])
    final=view(['A','K','M','E'],[['A','K'],['A','M'],['A','E']],angleArcs=[arc('A','K','E',1),arc('A','E','M',1)])
    rows=[
      step('Как получить две равноудалённые точки?','Окружностью с центром A отметим B и C на сторонах данного угла KAM. Радиусы AB и AC равны.','Определение окружности',[21,23]),
      step('Где взять точку будущей биссектрисы?','Построим окружности с центрами B и C, обе радиуса BC. Выберем точку их пересечения E внутри угла. Тогда BE=CE.','Окружности одинакового радиуса',[21,23]),
      step('Какие треугольники сравнить?','В △ABE и △ACE равны AB и AC, BE и CE, а AE — общая сторона. Поэтому эти треугольники равны по третьему признаку.','Третий признак равенства',[20,23]),
      step('Почему AE делит угол пополам?','Из равенства треугольников следует ∠BAE=∠CAE. Точка E выбрана внутри угла, поэтому луч AE — его биссектриса. Так можно разделить угол на две равные части.','Соответствующие углы и определение биссектрисы',[6,14,23])]
    return p,base,[first,second,proof,final],[equal(('A','B'),('A','C')),equal(('B','E'),('C','E'))],rows

def perpendicular_build():
    p={'M':(50,35),'A':(38,35),'B':(62,35),'P':(50,35+12*math.sqrt(3)),'Q':(50,35-12*math.sqrt(3))}
    base=view(['M'],lines=[['A','B']])
    first=view(['M','A','B'],lines=[['A','B']],circles=[circle('M','A')],equalSegments=[eq('M','A'),eq('M','B')])
    second=view(['M','A','B','P'],lines=[['A','B']],circles=[circle('A','B'),circle('B','A')])
    proof=view(['M','A','B','P'],[['P','A'],['P','B']],lines=[['A','B'],['M','P']],equalSegments=[eq('P','A'),eq('P','B'),eq('M','A',2),eq('M','B',2)])
    final=view(['M','P'],lines=[['A','B'],['M','P']],rightAngles=[right('P','M','B')])
    rows=[
      step('Как выбрать две точки на данной прямой?','Пусть M лежит на данной прямой. Окружностью с центром M отметим на противоположных лучах точки A и B. Получим MA=MB.','Построение равных отрезков на противоположных лучах',[21,22,23]),
      step('Как построить точку над прямой?','Проведём окружности с центрами A и B радиуса AB. Выберем любую точку их пересечения P. По построению PA=PB.','Равные радиусы построенных окружностей',[21,23]),
      step('Почему прямая MP перпендикулярна исходной?','Треугольник PAB равнобедренный, а M — середина AB. Его медиана PM к основанию является также высотой. Следовательно, PM⊥AB.','Медиана к основанию равнобедренного треугольника',[18,23]),
      step('Какой объект является ответом?','Проводим прямую MP. Она проходит через данную точку M и образует с данной прямой прямой угол. Вспомогательные окружности больше не нужны.','Проверка двух требований задачи',[12,23])]
    return p,base,[first,second,proof,final],[equal(('M','A'),('M','B')),equal(('P','A'),('P','B')),perp('M','P','A','B'),col('A','M','B')],rows

def midpoint_build():
    p={'A':(38,35),'B':(62,35),'P':(50,35+12*math.sqrt(3)),'Q':(50,35-12*math.sqrt(3)),'O':(50,35)}
    base=view(['A','B'],[['A','B']])
    first=view(['A','B','P','Q'],[['A','B']],circles=[circle('A','B'),circle('B','A')])
    second=view(['A','B','P','Q','O'],[['A','B']],lines=[['P','Q']])
    proof=view(['A','B','P','Q'],[['A','P'],['B','P'],['A','Q'],['B','Q'],['P','Q']],equalSegments=[eq('A','P'),eq('B','P'),eq('A','Q'),eq('B','Q')])
    final=view(['A','B','P','O'],[['A','B'],['A','P'],['B','P']],lines=[['P','Q']],equalSegments=[eq('A','O'),eq('O','B')],rightAngles=[right('P','O','B')])
    rows=[
      step('Какие вспомогательные окружности построить?','Для данного AB проведём две окружности радиуса AB: одну с центром A, другую с центром B. Обозначим их точки пересечения P и Q.','Построение окружности заданного радиуса',[21,23]),
      step('Где искать середину?','Проведём прямую PQ и обозначим O её пересечение с AB. Докажем, что AO=OB; пока это лишь кандидат на середину.','Проведение прямой через две точки',[1,22,23]),
      step('Как обосновать направление PQ?','В △APQ и △BPQ имеем AP=BP, AQ=BQ по построению, PQ — общая. По третьему признаку треугольники равны, поэтому ∠APQ=∠BPQ.','Третий признак равенства',[20,23]),
      step('Почему O — середина и PQ — серединный перпендикуляр?','PO — биссектриса равнобедренного APB. Поэтому PO одновременно медиана и высота: AO=OB и PQ⊥AB. Прямую через середину отрезка перпендикулярно ему называют серединным перпендикуляром.','Биссектриса равнобедренного треугольника; определение серединного перпендикуляра',[18,23])]
    return p,base,[first,second,proof,final],[equal(('A','P'),('B','P'),('A','Q'),('B','Q')),equal(('A','O'),('O','B')),col('A','O','B'),col('P','O','Q'),perp('P','Q','A','B')],rows

BUILDERS=[angle_copy,bisector_build,perpendicular_build,midpoint_build]

def combine_constructions():
    points={}; labels={}; scenes=[]; checks=[]; rows=[]; cases=[]; first=None
    names=['Перенос угла','Биссектриса','Перпендикуляр','Середина отрезка']
    for i,fn in enumerate(BUILDERS):
        p,initial,seq,cs,rs=fn(); mapping={k:f'{i}{k}' for k in p}
        def renamed(obj):
            if isinstance(obj,str):return mapping.get(obj,obj)
            if isinstance(obj,list):return [renamed(x) for x in obj]
            if isinstance(obj,dict):return {k:renamed(v) for k,v in obj.items()}
            return obj
        points.update({mapping[k]:v for k,v in p.items()});labels.update({mapping[k]:k for k in p})
        if first is None:first=renamed(initial)
        begin=len(rows)+1
        rows+=rs;scenes += [renamed(s) for s in seq];checks += [renamed(c) for c in cs]
        case=renamed(seq[-1]);case.update(label=names[i],availableFromStep=len(rows));cases.append(case)
    rows.append(step('Что ещё следует помнить о делении угла?','Построение биссектрисы делит любой обычный угол пополам. Разделить произвольный угол на три равные части только циркулем и линейкой в общем случае нельзя; это более поздний результат, здесь его доказательство не рассматривается. Для некоторых отдельных углов трисекция возможна.','Замечание учебника; границы утверждения',[23]))
    scenes.append(deepcopy(scenes[8]))
    return model(points,first,scenes,checks,cases,labels=labels),rows

constructions,construction_rows=combine_constructions()
