def select_model(original, indices):
    m=deepcopy(original)
    m['views']={'neutral':deepcopy(original['views']['neutral'])}
    for j,i in enumerate(indices,1):
        m['views'][f'step-{j}']=deepcopy(original['views'][f'step-{i}'])
        m['views'][f'step-{j}']['label']=f'Шаг {j}'
    return m

def question(n,title,statement,rows,answer,m):
    return add('selfcheck',n,title,[49 if n<=15 else 50],statement,rows,answer,m)

